def _quad(z):
    (i, j) = np.triu_indices(z.shape[1])
    return np.c_[_aff(z), z[:, i] * z[:, j]]

def _basis(t, traj):
    from scipy.optimize import least_squares

    def basis(k):
        return -np.expm1(-t[:, None] * k)

    def err(k):
        B = basis(k)
        return (B @ _ls(B, traj.T) - traj.T).ravel()
    rates = least_squares(err, [1.8, 0.4], bounds=([0.8, 0.03], [8.0, 0.79])).x
    return basis(rates)

def _latents(study, x):
    from scipy.optimize import least_squares
    panel = study['panel_a']
    (u, v) = (panel['u'], panel['v'])
    (a, b) = np.triu_indices(len(u), 1)
    du = u[a] - u[b]
    scale = np.nanmedian(np.divide(v[a] - v[b], du, where=abs(du) > 1e-10, out=np.full_like(du, np.nan)), axis=0)
    shift = np.median(v - u * scale, axis=0)
    for j in range(u.shape[1]):
        e = abs(v[:, j] - shift[j] - u[:, j] * scale[j])
        keep = e <= max(0.001, 6 * np.median(e))
        (shift[j], scale[j]) = _ls(_aff(u[keep, j]), v[keep, j])
    panel = study['panel_b']
    (u, v) = (panel['u'], panel['v'])

    def basis(z, p):
        return _aff(z * (p[2] + z ** 2 * (1 + z ** 2 * (p[0] + p[1] * z ** 2))))

    def residual(p):
        f = basis(u, p)
        return (f @ _ls(f, v) - v).ravel()
    p = least_squares(residual, [-0.45, 0.09, -0.09], gtol=1e-11).x
    return basis((x - shift) / scale, p) @ _ls(basis(u, p), v)

def _cross(h):
    (i, j) = np.triu_indices(h.shape[1], 1)
    return np.c_[_aff(h), h[:, i] * h[:, j]]

def _scalar(h, q, y):
    f = _cross(h)
    pen = np.diag(np.r_[np.zeros(5), np.full(f.shape[1] - 5, 0.03)])
    return _cross(q) @ np.linalg.solve(f.T @ f + pen, f.T @ y)
